class Solution {
  public long maxRectangleArea(int[] xCoord, int[] yCoord) {
    int n = xCoord.length;
    long[] pts = new long[n];
    for (int i = 0; i < n; i++) pts[i] = ((long) xCoord[i] << 27) | yCoord[i];
    java.util.Arrays.sort(pts);
    int[] ys = new int[n];
    for (int i = 0; i < n; i++) ys[i] = (int) (pts[i] & ((1 << 27) - 1));
    int[] sortedY = ys.clone();
    java.util.Arrays.sort(sortedY);
    int m = 0;
    for (int i = 0; i < n; i++)
      if (i == 0 || sortedY[i] != sortedY[i - 1]) sortedY[m++] = sortedY[i];
    // candidates: previous column x', current column x, y-range [lo, hi]
    int[] cx1 = new int[n], cx2 = new int[n], clo = new int[n], chi = new int[n];
    int cc = 0;
    java.util.HashMap<Long, Integer> last = new java.util.HashMap<>();
    for (int i = 1; i < n; i++) {
      long x = pts[i] >> 27, px = pts[i - 1] >> 27;
      if (x != px) continue;
      int y = ys[i], py = ys[i - 1];
      long key = ((long) py << 27) | y;
      Integer prev = last.put(key, (int) x);
      if (prev != null) {
        cx1[cc] = prev;
        cx2[cc] = (int) x;
        clo[cc] = py;
        chi[cc] = y;
        cc++;
      }
    }
    // offline: count points with x <= X and y in [lo, hi] using a Fenwick tree
    int[] qx = new int[2 * cc];
    int[] qid = new int[2 * cc];
    Integer[] order = new Integer[2 * cc];
    for (int c = 0; c < cc; c++) {
      qx[2 * c] = cx2[c];
      qx[2 * c + 1] = cx1[c] - 1;
      order[2 * c] = 2 * c;
      order[2 * c + 1] = 2 * c + 1;
    }
    java.util.Arrays.sort(order, (a, b) -> Integer.compare(qx[a], qx[b]));
    int[] bit = new int[m + 1];
    int[] cnt = new int[cc];
    int ptr = 0;
    for (int oi = 0; oi < order.length; oi++) {
      int q = order[oi], c = q / 2;
      while (ptr < n && (pts[ptr] >> 27) <= qx[q]) {
        int yi = java.util.Arrays.binarySearch(sortedY, 0, m, ys[ptr]) + 1;
        for (; yi <= m; yi += yi & -yi) bit[yi]++;
        ptr++;
      }
      int lo = java.util.Arrays.binarySearch(sortedY, 0, m, clo[c]) + 1;
      int hi = java.util.Arrays.binarySearch(sortedY, 0, m, chi[c]) + 1;
      int s = 0;
      for (int i = hi; i > 0; i -= i & -i) s += bit[i];
      for (int i = lo - 1; i > 0; i -= i & -i) s -= bit[i];
      cnt[c] += (q % 2 == 0) ? s : -s;
    }
    long best = -1;
    for (int c = 0; c < cc; c++) {
      if (cnt[c] == 4) best = Math.max(best, (long) (cx2[c] - cx1[c]) * (chi[c] - clo[c]));
    }
    return best;
  }
}
